SELECT CDSCode
FROM frpm
WHERE "Enrollment (K-12)" + "Enrollment (Ages 5-17)" > 500;

SELECT CAST(SUM(CASE WHEN DOC = 54 THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN DOC = 52 THEN 1 ELSE 0 END) AS ratio
FROM schools
WHERE StatusType = 'Merged' AND County = 'Orange';

SELECT Phone, Ext, School
FROM schools
WHERE Zip = '95203-3704';

SELECT CAST(SUM(CASE WHEN FundingType = 'Locally funded' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(FundingType) AS ratio_percentage
FROM schools
WHERE County = 'Santa Clara';

SELECT DisplayName
FROM users
WHERE strftime('%Y', CreationDate) = '2011';

SELECT COUNT(*) 
FROM users 
WHERE UpVotes > 100 AND DownVotes > 1;

SELECT COUNT(*) AS comment_count
FROM comments
WHERE PostId = (SELECT Id FROM posts WHERE ViewCount = 1910);

SELECT ViewCount
FROM posts
WHERE Title = 'Integration of Weka and/or RapidMiner into Informatica PowerCenter/Developer';

SELECT DisplayName
FROM users
WHERE WebsiteUrl = 'http://stackoverflow.com';

SELECT UserDisplayName
FROM comments
WHERE Text = 'thank you user93!';

SELECT COUNT(*) AS total_comments
FROM comments
WHERE UserId = 13;

SELECT Id
FROM users
WHERE Reputation = (SELECT MAX(Reputation) FROM users);

SELECT Id
FROM users
WHERE Views = (SELECT MIN(Views) FROM users);

SELECT Id, OwnerUserId
FROM posts
WHERE Score > 60;

SELECT COUNT(DISTINCT UserId) AS num_users
FROM badges
WHERE Name = 'Announcer';

SELECT DisplayName
FROM users
WHERE Views = (SELECT MAX(Views) FROM users);

SELECT
  (SELECT COUNT(Id) FROM votes WHERE strftime('%Y', CreationDate) = '2010') * 1.0 /
  (SELECT COUNT(Id) FROM votes WHERE strftime('%Y', CreationDate) = '2011') AS vote_ratio;

SELECT DisplayName, Age
FROM users
WHERE Views = (SELECT MAX(Views) FROM users);

SELECT LastEditDate, LastEditorUserId
FROM posts
WHERE Title = 'Detecting a given face in a database of facial images';

SELECT COUNT(*) AS tag_count
FROM tags
WHERE Count BETWEEN 5000 AND 7000;

SELECT Age
FROM users
WHERE Reputation = (SELECT MAX(Reputation) FROM users);

SELECT Id
FROM users
WHERE Age = (SELECT MIN(Age) FROM users);

SELECT DisplayName
FROM users
WHERE Age BETWEEN 19 AND 65;

SELECT Id, Title
FROM posts
WHERE Score = (SELECT MAX(Score) FROM posts);

SELECT SUM(CASE WHEN strftime('%Y', p.CreaionDate) = '2011' AND u.Reputation > 1000 THEN 1 ELSE 0 END) * 100.0 / COUNT(p.Id) AS percentage
FROM posts p
JOIN users u ON p.OwnerUserId = u.Id;

SELECT COUNT(*) AS TotalPostsAboveAverageViews
FROM posts
WHERE ViewCount > (SELECT AVG(ViewCount) FROM posts);

SELECT COUNT(*) 
FROM comments 
WHERE PostId = (SELECT Id FROM posts WHERE Score = (SELECT MAX(Score) FROM posts));

SELECT Reputation, Views
FROM users
WHERE DisplayName = 'Jarrod Dixon';

SELECT COUNT(DISTINCT PostId) AS NumPosts
FROM votes
WHERE BountyAmount >= 30;

SELECT ExcerptPostId, WikiPostId
FROM tags
WHERE TagName = 'sample';

SELECT SUM(CASE WHEN Currency = 'CZK' THEN 1 ELSE 0 END) - SUM(CASE WHEN Currency = 'EUR' THEN 1 ELSE 0 END) AS more_SMEs
FROM customers
WHERE Segment = 'SME';

SELECT 100.0 * SUM(CASE WHEN Currency = 'Euro' THEN 1 ELSE 0 END) / COUNT(*) AS percentage_of_KAM_paying_in_euros
FROM customers
WHERE Segment = 'KAM';

SELECT 100.0 * SUM(CASE WHEN Consumption > 528.3 THEN 1 ELSE 0 END) / COUNT(*) AS percentage
FROM yearmonth
WHERE Date = '201202';

SELECT SUM(CASE WHEN Segment = 'premium' THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS premium_percentage
FROM gasstations
WHERE Country = 'Slovakia';

SELECT SUM(CASE WHEN Segment = 'Premium' THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS premium_percentage
FROM gasstations
WHERE Country = 'SVK';

SELECT SUM(height) / COUNT(id) AS average_height
FROM Player
WHERE birthday >= '1990-01-01 00:00:00' AND birthday < '1996-01-01 00:00:00';

SELECT DISTINCT team_fifa_api_id
FROM Team_Attributes
WHERE buildUpPlaySpeed > 50 AND buildUpPlaySpeed < 60;

SELECT player_name
FROM Player
WHERE substr(birthday, 1, 7) = '1970-10';

SELECT player_name
FROM Player
WHERE height = (SELECT MAX(height) FROM Player);

SELECT player_name
FROM Player
WHERE datetime(CURRENT_TIMESTAMP, 'localtime') - datetime(birthday) > 34;

SELECT COUNT(CASE WHEN height < 180 AND overall_rating > 70 THEN 1 ELSE NULL END) * 100.0 / COUNT(Player.id) AS percentage
FROM Player
JOIN Player_Attributes ON Player.player_api_id = Player_Attributes.player_api_id;

SELECT COUNT(*) 
FROM account 
WHERE district_id IN (SELECT district_id FROM district WHERE A3 = 'Prague');

SELECT SUM(CASE WHEN status = 'C' THEN 1 ELSE 0 END) * 100.0 / COUNT(account_id) AS percentage
FROM loan
WHERE amount < 100000;

SELECT account_id
FROM account
WHERE frequency = 'POPLATEK MESICNE';

SELECT district_id AS branch_location, A2 AS district_name
FROM district
WHERE A13 = (SELECT MAX(A13) FROM district);

SELECT SUM(cost) AS total_pizza_cost
FROM expense
WHERE expense_description = 'Pizza';

SELECT DISTINCT department
FROM major
WHERE college LIKE 'College of Humanities%';

SELECT CAST(SUM(CASE WHEN major_name = 'Finance' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN major_name = 'Physics' THEN 1 ELSE 0 END) AS ratio
FROM major
JOIN member ON major.major_id = member.link_to_major;

SELECT first_name, last_name, email
FROM member
WHERE position = 'Secretary';

SELECT SUM(spent) * 1.0 / COUNT(spent) AS average_food_spending
FROM budget
WHERE category = 'Food' AND event_status = 'Closed';

SELECT SUM(type = 'Community Service') * 100.0 / COUNT(event_id) AS percentage
FROM event
WHERE event_date BETWEEN '2019-01-01' AND '2019-12-31';

SELECT SUM(m.position = 'Member' AND mj.major_name = 'Business') * 100.0 / COUNT(m.member_id) AS percentage
FROM member m
JOIN major mj ON m.link_to_major = mj.major_id;

SELECT CAST(SUM(b.remaining < 0) AS REAL) / COUNT(e.event_id) * 100 AS percentage_over_budget
FROM event e
JOIN budget b ON e.event_id = b.link_to_event;

SELECT event_id, location, status
FROM event
WHERE event_date BETWEEN '2019-11-01' AND '2020-03-31';

SELECT first_name, last_name
FROM member
WHERE t_shirt_size = 'X-Large';

SELECT COUNT(*) 
FROM superhero 
WHERE alignment_id = (SELECT id FROM alignment WHERE alignment = 'Bad');

SELECT COUNT(*) 
FROM superhero 
WHERE publisher_id = 1;

SELECT full_name
FROM superhero
WHERE weight_kg = 0 OR weight_kg IS NULL;

SELECT SUM(p.publisher_name = 'DC Comics') - SUM(p.publisher_name = 'Marvel Comics') AS difference
FROM superhero s
JOIN publisher p ON s.publisher_id = p.id;

SELECT superhero_name
FROM superhero
WHERE height_cm = (SELECT MAX(height_cm) FROM superhero);

SELECT COUNT(CASE WHEN CAST(strftime('%Y', Birthday) AS INTEGER) > 1930 THEN 1 END) * 100.0 / COUNT(ID) AS percentage
FROM Patient
WHERE SEX = 'F';

SELECT SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END) * 100.0 / COUNT(ID) AS percentage
FROM Patient
WHERE Birthday BETWEEN '1930-01-01' AND '1940-12-31';

SELECT CAST(COUNT(CASE WHEN Admission = '+' THEN 1 END) AS REAL) / COUNT(CASE WHEN Admission = '-' THEN 1 END) AS ratio
FROM Patient
WHERE Diagnosis = 'SLE';

SELECT School, City, AdmFName1, AdmLName1, AdmFName2, AdmLName2, AdmFName3, AdmLName3
FROM schools
WHERE Charter = 1 AND CharterNum = '00D2';

SELECT SUM(CASE WHEN FundingType = 'Locally funded' THEN 1 ELSE 0 END) * 100.0 / COUNT(FundingType) AS ratio_percentage
FROM schools
WHERE County = 'Santa Clara' AND FundingType IS NOT NULL;

SELECT AdmLName1, District, County, School
FROM schools
WHERE CharterNum = 40;

SELECT LastEditDate, LastEditorUserId
FROM posts
WHERE Title = 'Detecting a given face in a database of facial images';

SELECT 100.0 * COUNT(CASE WHEN strftime('%Y', p.CreaionDate) = '2011' AND u.Reputation > 1000 THEN p.Id END) / COUNT(p.Id) AS percentage
FROM posts p
JOIN users u ON p.OwnerUserId = u.Id;

SELECT COUNT(*) 
FROM comments 
WHERE PostId = (SELECT Id FROM posts WHERE Score = (SELECT MAX(Score) FROM posts));

SELECT
  (SELECT COUNT(*) FROM comments WHERE PostId = (SELECT Id FROM posts WHERE Title = 'Clustering 1D data')) AS comment_count,
  (SELECT COUNT(*) FROM posts WHERE ParentId = (SELECT Id FROM posts WHERE Title = 'Clustering 1D data') AND PostTypeId = 2) AS answer_count;

SELECT 100.0 * SUM(CASE WHEN p.Score > 50 THEN 1 ELSE 0 END) / COUNT(p.Id) AS percentage
FROM posts p
WHERE p.OwnerUserId = (SELECT Id FROM users ORDER BY Reputation DESC LIMIT 1);

SELECT CAST(SUM(CASE WHEN Currency = 'EUR' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS Percentage
FROM customers
WHERE Segment = 'KAM';

SELECT CAST(SUM(CASE WHEN Segment = 'Premium' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS PremiumPercentage
FROM gasstations
WHERE Country = 'Slovakia';

SELECT SUM(CASE WHEN Segment = 'Premium' THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS percentage
FROM gasstations
WHERE Country = 'SVK';

SELECT player_name
FROM (
    SELECT player_name, RANK() OVER (ORDER BY height DESC) AS rnk
    FROM Player
) AS ranked
WHERE rnk = 1;

SELECT SUM(CASE WHEN T1.height < 180 AND T2.overall_rating > 70 THEN 1 ELSE 0 END) * 100.0 / COUNT(T2.id) AS percentage
FROM Player AS T1
INNER JOIN Player_Attributes AS T2 ON T1.player_api_id = T2.player_api_id;
